package vn.rtr.aeris.phone06;
import java.io.*;import java.nio.*;import java.nio.file.*;import java.nio.channels.*;import java.util.*;
/** Initial PUBLIC policy import. Existing/uncertain files require explicit validation, never silent repair. */
public final class PhoneTrust06{
 public interface Validator{void validate(byte[]b)throws Exception;}public interface Commit{void commit(Path pending,Path target,byte[]b)throws Exception;default void confirmExisting(Path target)throws Exception{try(FileChannel file=FileChannel.open(target,StandardOpenOption.WRITE)){file.force(true);}try(FileChannel dir=FileChannel.open(target.getParent(),StandardOpenOption.READ)){dir.force(true);}}}
 public static final Commit DURABLE=(pending,target,bytes)->{try(FileChannel out=FileChannel.open(pending,StandardOpenOption.CREATE_NEW,StandardOpenOption.WRITE)){ByteBuffer b=ByteBuffer.wrap(bytes);while(b.hasRemaining())out.write(b);out.force(true);}Files.move(pending,target,StandardCopyOption.ATOMIC_MOVE);try(FileChannel dir=FileChannel.open(target.getParent(),StandardOpenOption.READ)){dir.force(true);}};
 public static Map<String,Object>install(Path root,byte[]b,Validator v)throws Exception{return install(root,b,v,DURABLE);}
 public static Map<String,Object>install(Path root,byte[]b,Validator v,Commit commit)throws Exception{if(b==null||b.length<2||b.length>16384||Files.isSymbolicLink(root)||!Files.isDirectory(root))throw new IOException("PHONE_TRUST_IMPORT_BOUND");v.validate(b);Path target=root.resolve("admin-trust.json"),pending=root.resolve("admin-trust-public-import.pending");if(Files.isSymbolicLink(target)||Files.isSymbolicLink(pending)||Files.exists(pending))throw new IOException("PHONE_TRUST_PENDING_OR_PATH_NO_RETRY");if(Files.exists(target)){if(!Files.isRegularFile(target)||Files.size(target)>16384||!Arrays.equals(Files.readAllBytes(target),b))throw new IOException("PHONE_TRUST_CONFLICT_NO_REPLACE");v.validate(b);commit.confirmExisting(target);return Data97.m("ok",true,"sha256",DraftStore.hash(b),"alreadyCommitted",true,"authorityRestorable",false);}commit.commit(pending,target,b);return Data97.m("ok",true,"sha256",DraftStore.hash(b),"alreadyCommitted",false,"authorityRestorable",false);}
}
